-- CadencePlus Solutions | Kora - 2025 only | PostgreSQL
-- Standalone seed script. No CSV path configuration is needed.
-- CAUTION: Re-running drops and recreates the Kora tables in the selected practice database.
-- Synthetic data, NGN, snapshot at 2025-12-31.

-- First create an empty PostgreSQL database named kora_starter and connect to it.
BEGIN;
CREATE SCHEMA IF NOT EXISTS kora;
SET search_path TO kora, public;
DROP TABLE IF EXISTS deliveries;
DROP TABLE IF EXISTS order_lines;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS branches;
DROP TABLE IF EXISTS regions;
CREATE TABLE regions (
  region_id VARCHAR(30) PRIMARY KEY,
  region_name VARCHAR(120) NOT NULL,
  country VARCHAR(120) NOT NULL
);
CREATE TABLE branches (
  branch_id VARCHAR(30) PRIMARY KEY,
  branch_name VARCHAR(150) NOT NULL,
  region_id VARCHAR(30) NOT NULL,
  city VARCHAR(100) NOT NULL,
  FOREIGN KEY (region_id) REFERENCES regions(region_id)
);
CREATE TABLE customers (
  customer_id VARCHAR(30) PRIMARY KEY,
  customer_name VARCHAR(150) NOT NULL,
  region_id VARCHAR(30) NOT NULL,
  industry VARCHAR(100) NOT NULL,
  segment VARCHAR(100) NOT NULL,
  FOREIGN KEY (region_id) REFERENCES regions(region_id)
);
CREATE TABLE products (
  product_id VARCHAR(30) PRIMARY KEY,
  product_name VARCHAR(150) NOT NULL,
  category VARCHAR(100) NOT NULL,
  unit_of_measure VARCHAR(50) NOT NULL,
  launch_date DATE NOT NULL,
  is_active SMALLINT NOT NULL
);
CREATE TABLE orders (
  order_id VARCHAR(30) PRIMARY KEY,
  order_date DATE NOT NULL,
  customer_id VARCHAR(30) NOT NULL,
  branch_id VARCHAR(30) NOT NULL,
  channel VARCHAR(100) NOT NULL,
  promised_delivery_date DATE NOT NULL,
  status VARCHAR(80) NOT NULL,
  cancellation_reason VARCHAR(255),
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
  FOREIGN KEY (branch_id) REFERENCES branches(branch_id)
);
CREATE TABLE order_lines (
  order_line_id VARCHAR(30) PRIMARY KEY,
  order_id VARCHAR(30) NOT NULL,
  product_id VARCHAR(30) NOT NULL,
  ordered_quantity INTEGER NOT NULL,
  list_unit_price_ngn DECIMAL(18,2) NOT NULL,
  discount_percent INTEGER NOT NULL,
  gross_order_value_ngn DECIMAL(18,2) NOT NULL,
  discount_value_ngn DECIMAL(18,2) NOT NULL,
  net_order_value_ngn DECIMAL(18,2) NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders(order_id),
  FOREIGN KEY (product_id) REFERENCES products(product_id)
);
CREATE TABLE deliveries (
  delivery_id VARCHAR(30) PRIMARY KEY,
  order_id VARCHAR(30) NOT NULL,
  branch_id VARCHAR(30) NOT NULL,
  carrier VARCHAR(120) NOT NULL,
  promised_delivery_date DATE NOT NULL,
  dispatch_date DATE,
  delivered_date DATE,
  status VARCHAR(80) NOT NULL,
  shipping_cost_ngn DECIMAL(18,2) NOT NULL,
  exception_reason VARCHAR(255),
  FOREIGN KEY (order_id) REFERENCES orders(order_id),
  FOREIGN KEY (branch_id) REFERENCES branches(branch_id)
);
COMMIT;
-- Run 02_Check_Load.sql to confirm load correctness.
